function profileIdentity(profile){return JSON.stringify([profile?.recipient,profile?.likes,profile?.dislikes,profile?.occasion,profile?.relationship,profile?.arrivalDeadline,profile?.audience,profile?.ageBand,profile?.expression,profile?.style,profile?.lifestyle]);}
